"use strict";

// Walkthroughs for the athlete-more family (see athlete-more-walkthroughs.js, walkthrough-kit.js and guide-walkthroughs.js), part b. Kept in its own file so two writers can work on one guide without touching the same lines.

const { S, W, OWN } = require("./walkthrough-kit.js");

module.exports = {
  // ---------------------------------------------------------------- the House settlement (a lesson)
  "house": {
    title: "Understanding the House settlement, the benefits cap and NIL Go",
    topic: "athlete-house", phrase: "the House settlement and NIL Go rules", us: true,
    steps: [
      S("Learn what the House settlement allows", "The NCAA has a question and answer document about the House settlement. It says schools that take part may give athletes direct payments and benefits, up to a yearly limit it calls the benefits cap. This is a lesson, not a form: you learn the rules so you can ask good questions of your school.", ["The NCAA question and answer page, open to read", "Paper and a pen"], "ncaaHouseQa", "you can say in your own words that taking-part schools may pay athletes directly, up to a yearly limit.", [W("House settlement", "the legal settlement that the NCAA's document explains, under which taking-part schools may pay athletes directly."), W("Benefits cap", "the yearly limit on the direct payments and benefits a school may give its athletes.")]),
      S("See how the cap is worked out, by the NCAA", "The NCAA document says the cap for 2025-26 is 20.5 million dollars. It is worked out as 22 percent of the average of eight revenue categories at the five defendant conferences and Notre Dame. It is recalculated every three years, and it rises 4 percent in the second and third year of each period. The NCAA president's June 2025 letter said 22.5 percent, so the official pages differ slightly on the percentage.", ["The NCAA question and answer page, open to read"], "ncaaHouseQa", "you know the 2025-26 figure, that it is a share of revenue, and that it is recalculated every three years.", [W("Revenue categories", "the kinds of money a school or conference takes in, which are added up to work out the cap.")]),
      S("See what the College Sports Commission says", "The College Sports Commission has its own page. It says each school can distribute up to approximately 21.58 million dollars for the 2026-27 academic year. It says the cap is 22 percent of the average revenue of the ACC, Big Ten, Big 12, Pac-12 and SEC schools from media rights, ticket sales and sponsorships. It rises 4 percent a year for the first three years, with a recalculation planned in year four.", ["The College Sports Commission page, open to read"], "cscAbout", "you know the 2026-27 figure and the three kinds of money the Commission says the cap is based on.", [W("College Sports Commission", "the group that runs NIL Go and publishes the cap figures for schools."), W("Media rights", "money paid to a conference or school to show its games.")]),
      S("Learn which deals count against the cap and which are reported", "The NCAA document says third-party NIL deals do not count against the cap. In Division I, deals of 600 dollars or more with outside payors are reported through NIL Go within five business days of agreeing the payment terms. Smaller deals from the same payor are added up. The guide does not say who files the report, so ask your school's compliance office.", ["Any NIL deal offer you have, to read", "The phone number or email of your school's compliance office"], "ncaaHouseQa", "you can say the 600 dollar line and the five business day limit, and you know who to ask about who reports.", [W("NIL", "name, image and likeness: being paid for the use of your name, your picture or your fame."), W("NIL Go", "the system, run by the College Sports Commission, through which Division I deals of 600 dollars or more are reported."), W("Compliance office", "the school office that explains the rules to athletes.")]),
      S("Know how a deal with a school-linked person is checked", "For a deal with a school-associated entity or person, the Commission checks two things. One is a valid business purpose, which the July 2025 document describes as promotion or endorsement of goods or services offered to the general public for profit. The other is pay within a reasonable range for similar people.", ["The NCAA July 2025 question and answer page, open to read"], "ncaaHouseQa2025", "you can name the two things the Commission checks for a deal with a school-linked person.", [W("School-associated entity or person", "a business or person connected to your school, for example one that supports its teams."), W("Valid business purpose", "a real job for the money, such as promoting something sold to the public.")]),
      S("Know your choices if a deal is not cleared", "The NCAA document says that if a deal is not cleared, the athlete can revise it with the payor, cancel it and refund, or appeal to a neutral arbitrator. The arbitrator has 45 days and the decision is final and binding. Going ahead with a deal that was not cleared may bring enforcement, which could include loss of eligibility. So do not go ahead before you have asked.", ["The NCAA question and answer page, open to read"], "ncaaHouseQa", "you can list the three choices and say what could happen if you go ahead without clearance.", [W("Arbitrator", "a neutral person who decides a dispute instead of a court."), W("Final and binding", "the decision cannot be appealed and both sides must accept it.")]),
      S("Learn what the school must report and what the fine is", "The Commission's revenue-sharing page says schools report revenue-share payments through its College Athlete Payment System within five business days of final signature. In 2026-27 a school that goes over the cap because of new scholarships is fined 20 cents for every dollar over, for up to 2.5 million dollars of that spending. That overage is planned not to count from 2027-28, subject to NCAA approvals. I found no official page saying whether the settlement is being appealed, so ask your compliance office.", ["The College Sports Commission revenue-sharing page, open to read", "Your list of questions for the compliance office"], "cscRevenue", "you have written your questions for the compliance office, and you know the guide does not say whether the settlement is being appealed.", [W("Revenue share", "money a school pays directly to its athletes from the school's own revenue.")])
    ]
  },

  // ---------------------------------------------------------------- an agent and college eligibility
  "agent-eligibility": {
    title: "Checking how an agent could affect a college athlete's eligibility",
    topic: "athlete-agent-eligibility", phrase: "how an agent affects a college athlete's eligibility", us: true,
    steps: [
      S("Learn who the NCAA counts as an agent", "Before you talk to anyone, learn the NCAA's word. Its Division I bylaws define an agent broadly. An agent is anyone who represents or tries to represent an athlete to market their athletics ability or reputation for financial gain. That may include a contract advisor, a financial advisor, a marketing representative or a brand manager. So the word can cover more people than you think.", ["The NCAA agent exam resource, open to read", "Paper and a pen"], "ncaaAgentBylaws", "you can name at least two kinds of people the NCAA may count as an agent.", [W("Bylaw", "a written rule of the NCAA."), W("Division I", "the NCAA's top level of college sport."), W("Eligibility", "your right to play for a college team under the rules.")]),
      S("Learn the rule about ever agreeing to be represented", "Bylaw 12.3.1 says a person is ineligible in a sport if they ever agreed, orally or in writing, to be represented by an agent for that purpose. Orally means in spoken words, so an agreement does not have to be on paper. An agreement that is not limited in writing to particular sports counts for all sports.", ["The NCAA agent exam resource, open to read"], "ncaaAgentBylaws", "you can say that a spoken agreement can cost eligibility, and that an agreement with no sport named counts for all sports.", [W("Ineligible", "not allowed to play for a college team under the rules.")]),
      S("Learn the rule about gifts and benefits", "Bylaw 12.3.1.4 says accepting transportation or other benefits from an agent also costs eligibility. This is true even if the agent says he has no interest in representing you. It includes benefits given to your family and friends.", ["The NCAA agent exam resource, open to read"], "ncaaAgentBylaws", "you can say that benefits to you, your family or your friends from an agent can cost you eligibility.", []),
      S("Learn about lawyers and the exceptions", "Bylaw 12.3.2 says advice from a lawyer about a proposed professional contract is not an agent agreement, unless the lawyer also negotiates for you. There are exceptions. Baseball and men's ice hockey players drafted before full-time enrollment may use an agent or attorney in contract negotiations. A men's basketball player may sign with an NCAA-certified agent after his season ends and after requesting an NBA evaluation.", ["The NCAA agent exam resource, open to read"], "ncaaAgentBylaws", "you can say when a lawyer's advice is not an agent agreement, and name one of the exceptions.", [W("Negotiate", "to talk with the other side to agree on the terms of a deal."), W("Draft", "the yearly event where professional teams choose players.")]),
      S("Learn what the football memo says about contact", "The NCAA's football memo says no to any agreement with an agent or a runner. It says contact alone is not prohibited if there is no agreement and no benefits. So you may talk to someone, but you should agree to nothing and accept nothing.", ["The NCAA football memo, open to read"], "ncaaNflMemo", "you can say what is allowed, which is contact, and what is not, which is an agreement or a benefit.", [W("Runner", "a person who works for an agent to find and approach athletes.")]),
      S("Learn about the April 2026 change for new prospects", "An NCAA news item of 15 April 2026 says the Division I Cabinet changed the rules for prospects enrolling in 2026-27. Those prospects may now sign with professional sports agents before enrolling in college, accept prize money in their sport, and enter a draft once, without it affecting eligibility. The bylaw text I read predates that change and still says ever. The NBA, NFL and MLB memos also say that under Division I rules, using an agent for NIL activities is permissible.", ["The NCAA news item, open to read"], "ncaaProspects2026", "you know the change applies to prospects enrolling in 2026-27, and that the older bylaw text still says ever.", [W("Prospect", "a person who has not yet enrolled in college but may play there."), W("NIL", "name, image and likeness: being paid for the use of your name, picture or fame.")]),
      S("Ask your compliance office before you sign anything", OWN + "The guide says to confirm with your compliance office before you sign anything. Write down the name of the person you want to sign with, what they offered you, and the questions you want to ask. Then ask the office, and write down the answer and the date. Do not sign first and ask later.", ["Paper and a pen", "The phone number or email of your school's compliance office"], null, "you have asked your compliance office about this person and written down the answer and the date.", [W("Compliance office", "the school office that explains the NCAA rules to athletes.")])
    ]
  },

  // ---------------------------------------------------------------- liability waivers
  "waiver": {
    title: "Understanding a liability waiver for a youth sports program",
    topic: "athlete-waiver", phrase: "a liability waiver for a youth sports program", us: true,
    steps: [
      S("Know that the rules differ by state", "A waiver is a paper a parent signs, saying the program is not blamed if the child is hurt. I found no state attorney general, bar or court page that explains waivers in plain words. What can be read is state law and court decisions, and they differ by state. A Florida Senate analysis from 2010 says there is no general rule on parental waivers. Whether a parent's waiver for a minor is enforced depends on the state's common law and statutes.", ["The Florida Senate analysis, open to read", "Paper and a pen"], "flWaiverAnalysis", "you can say that whether a waiver holds depends on the state.", [W("Waiver", "a signed paper in which a person gives up the right to blame someone if they are hurt."), W("Minor", "a child under the legal age of adulthood."), W("Enforced", "made to count by a court.")]),
      S("See how many states the study found", "The same Florida analysis quotes a 2007 study. It found parental waivers likely enforced under some circumstances in at least 11 states, unlikely in 14, and unanswered in about half of the states. The analysis says its table is dated. Treat these as a picture of how mixed the rules are, not as an answer for your state.", ["The Florida Senate analysis, open to read"], "flWaiverAnalysis", "you can say the study found the answer mixed, and unanswered in about half the states.", []),
      S("Read what the Ohio court decided", "The Ohio Supreme Court held in 1998 that parents may bind their minor children to waivers in favor of volunteers and sponsors of nonprofit sport activities, where the claim is negligence. This is one state's court decision. It does not mean the same is true where you live.", ["The Ohio Supreme Court decision, open to read"], "ohioZivich", "you can say what the Ohio court decided and that it is only one state's decision.", [W("Negligence", "failing to take the care a careful person would take."), W("Nonprofit", "an organization that does not exist to make money for its owners.")]),
      S("Read what Michigan's law says", "Michigan's law lets a parent release a person in writing for a minor's injury in a recreational activity run by a nonprofit. It covers only injury or death resulting solely from inherent risks, not the other party's negligence. So the Michigan release is narrower than the Ohio decision.", ["The Michigan law, open to read"], "michiganWaiver", "you can say what Michigan's release covers and what it does not.", [W("Inherent risks", "the dangers that are part of the activity itself.")]),
      S("Read what Montana's law says", "Montana's law says a waiver before a sport or recreational opportunity can cover ordinary negligence or inherent risks. It must state the known inherent risks and carry a bold warning about the right to a jury trial. It can still be challenged. It does not mention minors.", ["The Montana law, open to read"], "montanaWaiver", "you can name the two things Montana's law says a waiver must have.", [W("Jury trial", "a court case decided by a group of ordinary citizens.")]),
      S("Ask a lawyer in your state", OWN + "I cannot say whether a waiver would hold where you are. A lawyer in your state can. Write down your state, who runs the activity, whether it is a nonprofit, and whether the people in it are children. Then take the waiver and your notes to a lawyer in your state.", ["The waiver you are thinking of using or signing", "Paper and a pen"], null, "you have written your state and the facts about the activity, and you know to take them to a lawyer in your state.", [])
    ]
  },

  // ---------------------------------------------------------------- pensions, benefits and disability cover
  "pension": {
    title: "Learning about league pensions, benefits and disability cover",
    topic: "athlete-pension", phrase: "league pensions and disability cover for athletes", us: true,
    steps: [
      S("Learn how the football players' pension works", "What the players' own pages say differs a lot by league. The NFL Players Association says a player with three credited seasons is vested. For former players it lists a Pension Plan with lifetime monthly benefits for vested players starting at age 55, or deferred to 65 for a higher monthly amount, and an Annuity Program. Its pages give no dollar amounts and do not define a credited season.", ["The NFL Players Association page, open to read", "Paper and a pen"], "nflpaFormer", "you can say what vested means on that page and that the page gives no dollar amounts.", [W("Vested", "having earned the right to keep a benefit."), W("Pension", "money paid to you every month after you stop working."), W("Annuity", "a plan that pays you money over time.")]),
      S("Learn the other football benefits listed", "The same players' association lists a Capital Accumulation Plan and a Second Career Savings Plan with distributions from age 45. It lists a severance lump sum for two or more credited seasons, a disability and survivor plan, and five years of free extended medical coverage for three or more credited seasons. Again, the pages give no dollar amounts.", ["The NFL Players Association page, open to read"], "nflpaFormer", "you can name three of the benefits and the number of credited seasons one of them needs.", [W("Severance", "a one-time payment when you leave."), W("Survivor plan", "a plan that pays your family if you die.")]),
      S("Learn what the hockey retiree fund is", "For hockey, the NHL and the NHL Players' Association announced in September 2025 a retiree healthcare and wellness fund. Each side puts in 2 million dollars a year. It is for alumni with catastrophic health problems and no insurance, and for wellness. I could not read current pension rules for Major League Baseball, the NBA or Major League Soccer from official pages, and the WNBA's agreement was only tentative, so I will not state them.", ["The NHL announcement, open to read"], "nhlRetireeFund", "you can say who the hockey fund is for, and you know the guide does not state baseball, NBA or soccer pension rules.", [W("Catastrophic", "very serious and life-changing."), W("Alumni", "former players.")]),
      S("Ask for the summary plan description of any plan you are in", "The U.S. Department of Labor says that for any plan you are in, you can ask for the summary plan description, which describes the plan's key rules. A defined benefit plan sends a benefit statement every three years. Employer contributions to such a plan generally vest 100 percent after five years, or in steps from three to seven years. A union plan's own rules govern.", ["A list of every plan you are in", "The Department of Labor page, open to read"], "dolSpdFaq", "you can say what a summary plan description is and that you are allowed to ask for it.", [W("Summary plan description", "a document that describes a plan's key rules."), W("Defined benefit plan", "a plan that promises a set benefit, such as a monthly pension.")]),
      S("Learn how Social Security disability works", "The Social Security Administration says you must have worked in jobs it covers and have a medical condition that meets its strict definition of disability. Generally that is one that stops you working for a year or more. There is generally a five-month waiting period, with the first benefit paid in the sixth full month. You generally need 40 work credits, 20 of them earned in the last 10 years, though younger workers may need fewer. In 2026 one credit takes 1,890 dollars of earnings in a quarter.", ["The Social Security Administration page, open to read"], "ssaEligibility", "you can say the waiting period and how many work credits are generally needed.", [W("Work credit", "a unit of earnings that counts toward Social Security benefits."), W("Waiting period", "the time you must wait before the first payment.")]),
      S("Learn how private disability insurance differs", "The insurance regulators' association, the NAIC, says private disability insurance typically replaces about 60 percent of pre-disability income, often after a waiting period such as 30 days. Policies differ on whether they pay if you cannot do your own occupation or only if you cannot do any work. I found nothing in these pages that is specific to athletes' disability cover.", ["The NAIC page, open to read"], "naicDisability", "you can say the two ways a policy may decide whether to pay.", [W("Own occupation", "your own kind of job, for example playing your sport."), W("Disability insurance", "insurance that pays part of your income if illness or injury stops you working.")]),
      S("Write down your plans and your questions", OWN + "Make a list of every plan, union benefit and insurance policy you have or could have. Next to each one, write the question you want answered, and who you will ask. You can also ask me about money after sport. I cannot tell you which plan fits you. A professional who knows the plans can.", ["Paper and a pen", "Any papers you already have from a plan or a policy"], null, "you have a written list of your plans and one question beside each.", [])
    ]
  },

  // ---------------------------------------------------------------- World Athletics representatives
  "wa-reps": {
    title: "Checking a World Athletics representative before you sign",
    topic: "athlete-wa-reps", phrase: "checking a World Athletics representative before signing",
    steps: [
      S("Learn who must use a licensed representative", "World Athletics says its Athletes' Representatives Rules were adopted on 14 August 2023, and licensing opened on 1 September 2023. From 1 January 2024, certain ranked athletes, and athletes in certain elite competitions, must use only World Athletics-licensed representatives. A ranked athlete has three choices: a licensed representative, the athlete's own member federation if World Athletics has given it permission, or representing yourself.", ["The World Athletics representatives page, open to read", "Paper and a pen"], "waAthleteReps", "you can name the three ways a ranked athlete may be represented.", [W("Representative", "an agent or manager who acts for an athlete."), W("Member federation", "your country's athletics body, which belongs to World Athletics."), W("Licensed", "approved by World Athletics to act as a representative.")]),
      S("Find out whether you count as a ranked athlete", "The rules define a ranked athlete by World Rankings. That means the top 100 in a track event, the top 50 in a field event, the top 200 in the marathon, and the top 200 in road running from the half marathon to 10 kilometres. It also means the top 50 in race walking, the top 75 in cross country, and the top 35 in combined events. Check your own ranking against these lines.", ["Your World Rankings position in each of your events"], "waRepRules", "you know whether you are inside any of those lines in your event.", [W("World Rankings", "the list that orders athletes by their results.")]),
      S("Check the licence before you sign", "The rules say an athlete must check that a representative is licensed before signing. They also say a coach or anyone in an athlete's entourage is strictly prohibited from acting as a representative unless licensed. The guide does not say how to look up a licence, so ask World Athletics through its representatives page.", ["The name of the person who wants to represent you", "The World Athletics representatives page"], "waRepRules", "you have asked World Athletics whether this person is licensed, or you have decided not to go on.", [W("Entourage", "the people around an athlete, such as a coach, a friend or a manager.")]),
      S("Read what the written agreement must say", "A representative may act only under a written agreement. It may not run longer than two years, and can be extended by agreement one year at a time. It must name the parties, the length, the service fee and what the services are. The representative must advise you in writing to consider independent legal advice. A clause that penalises you for not renewing is invalid.", ["The draft agreement, to read slowly", "A pen to mark anything missing"], "waRepRules", "you have checked the agreement for the parties, the length, the fee and the services, and marked anything missing.", [W("Independent legal advice", "advice from a lawyer who does not work for the other side."), W("Invalid", "not allowed, so it does not count.")]),
      S("Check the fee", "The rules say the fee must not be abusive or excessive and must be linked to the benefits agreed. The rules set no percentage cap, so a number is not automatically right or wrong. Disputes go to a World Athletics panel. Write down the fee in the draft and what you get for it.", ["The draft agreement", "Paper and a pen"], "waRepRules", "you have written down the fee and the benefits it is linked to.", [W("Excessive", "far more than is fair.")]),
      S("If the athlete is a minor, check the extra rules", "For a minor, a representative may approach the athlete or guardian no more than six months before the legal working age. The representative needs the guardian's written consent, and may not take a fee until that age. If this is about a young athlete, check each of these three before anything is signed.", ["The age of the athlete and the legal working age where you live"], "waRepRules", "you have checked the six month limit, the guardian's written consent and that no fee is taken before the working age.", [W("Guardian", "the adult legally responsible for a child."), W("Legal working age", "the age at which a young person may legally work.")]),
      S("Ask your federation about its permission", "The World Athletics page lists nine federations with permission to act for athletes until 31 December 2026. I did not find Kenya on it and could not confirm Nigeria. So if you are in Kenya or Nigeria, ask your own federation whether it has permission before you rely on it as your representative.", ["The name of your federation", "The World Athletics representatives page"], "waAthleteReps", "you have asked your federation whether it has World Athletics permission, and written down the answer.", [])
    ]
  },

  // ---------------------------------------------------------------- transfer of allegiance
  "allegiance": {
    title: "Understanding a World Athletics transfer of allegiance",
    topic: "athlete-allegiance", phrase: "a transfer of allegiance in World Athletics",
    steps: [
      S("Know who may apply", "A transfer of allegiance is changing the country you represent in athletics. World Athletics' regulations were approved on 19 March 2026 and are effective from 27 March 2026. They say only a member federation can apply: an athlete cannot apply directly. Applications can be made in one of two periods each calendar year.", ["The World Athletics transfer regulations, open to read", "Paper and a pen"], "waTransfer", "you can say that only a federation applies, and that there are two periods a year.", [W("Transfer of allegiance", "changing the country you represent in athletics."), W("Member federation", "your country's athletics body, which belongs to World Athletics.")]),
      S("Learn the conditions for the athlete", "Under the eligibility rules, an athlete who has already represented a country must wait three years from the date the application is made. During that time they must not represent any member federation in national representative competitions or other relevant competitions. They must be at least 20 by the end of the waiting period, must be a citizen of the new country, and must have a genuine, close, credible and established link, for example through residence. If the athlete competes in those competitions early, the waiting period starts again from that date.", ["The World Athletics eligibility rules, open to read"], "waEligibility", "you can name the three year wait, the age of 20, citizenship and the link to the new country.", [W("Citizen", "a person who legally belongs to a country."), W("Waiting period", "the time you must wait before the change can happen.")]),
      S("Learn the limits on transfers", "As a general rule an athlete may transfer once. A second transfer is allowed only in exceptional circumstances, and only back to the original federation. Federations cannot agree between themselves to shorten the waiting period. Each federation may submit at most ten applications in a four-year Olympic cycle, and no more than two athletes from any one other federation, one man and one woman.", ["The World Athletics transfer regulations, open to read"], "waTransfer", "you can say how many transfers an athlete may generally make, and that the wait cannot be shortened by agreement.", [W("Olympic cycle", "the four years between Olympic Games.")]),
      S("Know what the application must disclose", "The application must disclose any payments offered to the first federation or the athlete. It must also give the name of any athlete representative or agent involved and any fees they received. The athlete can withdraw support for the application at any time before it is granted, and can then compete again for the first federation.", ["The World Athletics transfer regulations, open to read", "A list of anyone who has offered you money or help"], "waTransfer", "you know what must be disclosed and that you may withdraw your support before the transfer is granted.", [W("Disclose", "to tell openly, in writing.")]),
      S("Know how to challenge a decision, and what the guide cannot say", "A decision can be challenged by a request for reconsideration and then an appeal to the Court of Arbitration for Sport within thirty days of the written reasons. These regulations do not govern selection for the Olympic Games. They do not give the administration fee, and I cannot tell you whether a particular transfer would be approved. Your own member federation is the body that can apply, so talk to it.", ["The name of your member federation", "Paper and a pen for your questions"], "waTransfer", "you know the thirty day limit for an appeal and have written the questions to ask your federation.", [W("Court of Arbitration for Sport", "the international court that decides sport disputes."), W("Reconsideration", "asking the decider to look at the decision again.")])
    ]
  },

  // ---------------------------------------------------------------- Kenya tax and saving
  "kenya-money": {
    title: "Learning about tax and saving for an athlete in Kenya",
    topic: "athlete-kenya-money", phrase: "tax and saving for an athlete in Kenya",
    steps: [
      S("Know what the Kenya Revenue Authority taxes", "The Kenya Revenue Authority's page on individual income tax says tax is charged on all income of a person, resident or not, that accrued in or was derived from Kenya. That means income you earned in Kenya or that came from Kenya. This is a lesson, not tax advice: you learn what the page says so you can ask good questions.", ["The Kenya Revenue Authority income tax page, open to read", "Paper and a pen"], "kraIncomeTax", "you can say in your own words what kind of income the page says is taxed.", [W("Resident", "a person who lives in Kenya as the tax law defines it."), W("Accrued", "earned, even if it is not yet paid to you.")]),
      S("Read the tax bands and the personal relief", "The page lists yearly bands, shown as effective from 1 July 2023. It is 10 percent on the first 288,000 shillings, 25 percent on the next 100,000, 30 percent on the next 5,612,000, 32.5 percent on the next 3,600,000, and 35 percent above 9,600,000. Residents get a personal relief of 28,800 shillings a year. The rates may have changed since the dates on those pages, so confirm the current ones.", ["The income tax page, open to read"], "kraIncomeTax", "you can read out the first two bands and the personal relief, and you know to confirm the current rates.", [W("Band", "a slice of income taxed at one rate."), W("Personal relief", "an amount taken off your tax.")]),
      S("Learn how to get a PIN", "To get a PIN you register on the iTax portal as an individual. You complete sections for basic information, obligations and source of income. Residents need their national ID. You do this yourself on the official page.", ["Your national ID, to look at while you fill in the form", "The KRA PIN registration page, open"], "kraPin", "you know the three sections of the registration and that a resident needs the national ID.", [W("PIN", "personal identification number: the number the tax authority uses to know you."), W("iTax", "the Kenya Revenue Authority's online system for tax.")]),
      S("Learn when the return is due and the penalty", "Returns are filed on iTax between 1 January and 30 June of the following year. Every person with a PIN must file each year, even if the return is nil. The late-filing penalty is the higher of 5 percent of the tax due or 2,000 shillings. Write the dates on your calendar so you are not caught out.", ["A calendar or diary", "The income tax page, open"], "kraIncomeTax", "you have written 1 January to 30 June on your calendar and can say that a nil return must still be filed.", [W("Nil return", "a tax return that says you owe nothing."), W("Penalty", "an extra charge for doing something late.")]),
      S("Learn about withholding on winnings and fees", "The KRA withholding page lists 20 percent on winnings from betting, gaming and prize competitions, for residents and non-residents. It lists 20 percent for non-residents on artists and entertainers, and 5 percent for residents on professional, management, consultancy and marketing fees. It has no rate for sportspeople, appearance fees or race prize money, and does not say which heading prize money from a race falls under. I found no KRA page about athletes, so ask the KRA before assuming.", ["The KRA withholding page, open to read", "Your race or prize papers, if you have any"], "kraWithholding", "you know the page has no rate for race prize money, and you have a question written to ask the KRA.", [W("Withholding tax", "tax taken out of a payment before it reaches you."), W("Non-resident", "a person who does not live in Kenya as the tax law defines it.")]),
      S("Learn how to save for retirement with the NSSF", "The National Social Security Fund says self-employed people can register as voluntary members with their ID at any NSSF office. The minimum to activate is 200 shillings, and you can top up by mobile money. This is one way to save for the years after sport.", ["Your national ID", "The NSSF voluntary member page, open to read"], "nssfVoluntary", "you can say who may register as a voluntary member, what to bring and the minimum to activate.", [W("Voluntary member", "a person who joins the fund by choice, not through an employer.")])
    ]
  },

  // ---------------------------------------------------------------- athletics in Nigeria
  "nigeria": {
    title: "Finding out how athletics is run in Nigeria and who to contact",
    topic: "athlete-nigeria", phrase: "how athletics is run in Nigeria and who to contact",
    steps: [
      S("Know the governing body and where it is", "The Athletics Federation of Nigeria says on its site that it is the governing body for athletics in Nigeria, affiliated to the Confederation of African Athletics and World Athletics. Its secretariat is at the Moshood Abiola National Stadium Complex in Abuja. It is open Monday to Friday, 9 a.m. to 5 p.m., with the email info@athleticsnigeria.org.", ["The federation page, open to read", "Paper and a pen"], "afnHome", "you have written down where the secretariat is, its hours and its email.", [W("Federation", "the body that runs a sport in a country."), W("Secretariat", "the office that does the federation's daily work.")]),
      S("Ask the secretariat what you need to do", "The federation's pages on athlete information and forms say athletes can get the latest information from the secretariat. But they list no steps, fees or downloads. So the steps are not on the page, and you have to ask. Write your questions first, then email or visit during the hours you wrote down.", ["Your written questions", "A way to email, or the means to visit during office hours"], "afnHome", "you have sent or taken your questions to the secretariat, or you have the day and time when you will.", []),
      S("Learn about Roster Athletics and the planned licence", "In January 2026 the government's Voice of Nigeria reported that the federation launched Roster Athletics, an online registration platform. It also plans a compulsory licensing system where each registered athlete would get one licence number for their whole career, renewed every year and linked to international athletics databases. The report gives no fees, no date when licensing becomes compulsory and no penalties.", ["The Voice of Nigeria report, open to read"], "vonRoster", "you can say what Roster Athletics is, and that the report gives no fees or start date.", [W("Licence", "official permission, here to compete as a registered athlete."), W("Compulsory", "required, not optional.")]),
      S("Learn what the Podium Board does", "The National Sports Commission said that it inaugurated an Elite Athletes Development and Podium Board in January 2025. The board is to run a high-performance system, identify talent and oversee how athletes are selected and prepared for major events. This is the Commission's own report.", ["The Federal Ministry report, open to read"], "fminoPodium", "you can name two things the Podium Board is meant to do.", [W("National Sports Commission", "the national government body for sport in Nigeria."), W("High-performance", "aimed at the very top level of sport.")]),
      S("Learn about the training grants", "In October 2025 the Commission said the board gives athletes training grants before competitions. It did not give amounts. That is the Commission's own report. The guide does not say how a grant is asked for, so ask the federation's secretariat.", ["The Federal Ministry report, open to read", "Your list of questions for the secretariat"], "fminoOneYear", "you know grants were reported, that no amounts were given, and you have added a grant question to your list.", [W("Grant", "money given for a purpose, which you do not pay back.")]),
      S("Learn about the study and sport programme, and what is not known", "In August 2026 the Federal Ministry of Education and the Commission announced a programme combining study and elite sport at nine institutions, starting with four. The report mentions no scholarships. The Commission's own website would not load, so I cannot give its rules on athlete welfare, managers or contracts. For agents and managers, ask me about the World Athletics representative rules.", ["The Voice of Nigeria report, open to read"], "vonNseep", "you know the programme was announced, no scholarships were mentioned, and the guide cannot give the Commission's rules on welfare, managers or contracts.", [W("Institution", "a school, college or university.")])
    ]
  },

  // ---------------------------------------------------------------- Nigeria tax
  "nigeria-money": {
    title: "Learning how the Nigeria Tax Act treats an athlete's income",
    topic: "athlete-nigeria-money", phrase: "tax for an athlete in Nigeria",
    steps: [
      S("Learn what income the Act lists", "The Nigeria Tax Act, 2025, in the official gazette copy on the National Assembly's site, lists chargeable income. That includes profits from a trade, business, profession or vocation. It includes fees, dues, allowances or any remuneration for services. It also includes prizes, winnings, honoraria, grants and awards. This is a lesson, not tax advice.", ["The Nigeria Tax Act, open to read", "Paper and a pen"], "nigeriaTaxAct", "you can name three kinds of income the Act lists as chargeable.", [W("Chargeable income", "income that the law says can be taxed."), W("Remuneration", "payment for work or services."), W("Honorarium", "a payment given for a service, often small.")]),
      S("Learn what can be taken off", "An individual's chargeable income is total income less eligible deductions. These include contributions to the National Housing Fund, the National Health Insurance Scheme and pensions, home-loan interest, and life insurance premiums. There is also rent relief of 20 percent of annual rent, up to 500,000 naira.", ["The Nigeria Tax Act, open to read", "Your records of rent and contributions, if you have them"], "nigeriaTaxAct", "you can name two deductions and the cap on the rent relief.", [W("Deduction", "an amount you may take off your income before tax is worked out."), W("Premium", "a regular payment for insurance.")]),
      S("Read the tax rates", "The Act's Fourth Schedule gives the rates on income after relief and exemptions. It is 0 percent on the first 800,000 naira, 15 percent on the next 2.2 million, 18 percent on the next 9 million, 21 percent on the next 13 million, 23 percent on the next 25 million, and 25 percent above 50 million. Each slice of income is taxed at its own rate.", ["The Nigeria Tax Act, open to the Fourth Schedule"], "nigeriaTaxAct", "you can read out the first two rates and say that each slice has its own rate.", [W("Schedule", "a table of figures at the back of a law."), W("Exemption", "income the law says is not taxed.")]),
      S("See where prize money fits", "I searched the Act for athletes and sponsorship and found no sport-specific provision. So prize money falls under the general lines you have already read, which list prizes, winnings and awards.", ["The Nigeria Tax Act, open to read"], "nigeriaTaxAct", "you can say that the Act has no special rule for athletes, so prize money falls under the general lines.", []),
      S("Write your questions for a tax professional in Nigeria", OWN + "I could not read the Nigeria Tax Administration Act or the revenue service's pages, so I cannot tell you how to get a tax ID, when to file or who collects. I did not confirm the Act's effective date on an official page. A tax professional in Nigeria can say how this applies to an athlete who earns abroad. Write your questions down before you go.", ["Paper and a pen", "A list of your kinds of income, such as prizes and fees, and where each is paid"], null, "you have a written list of questions about the tax ID, when to file, who collects and the effective date.", [W("Tax professional", "a trained person who helps with tax, such as an accountant.")])
    ]
  },

  // ---------------------------------------------------------------- NCAA and NAIA for international athletes
  "abroad-eligibility": {
    title: "Learning the NCAA and NAIA rules for an international athlete",
    topic: "athlete-abroad-eligibility", phrase: "learning the NCAA and NAIA eligibility rules for an international athlete",
    steps: [
      S("Learn the school marks the NCAA asks for", "The NCAA says an international Division I athlete needs 16 core courses and a core GPA of at least 2.3. Division II needs 16 and a 2.2. Division III schools set their own standards. The Eligibility Center certifies athletics eligibility. This is a lesson: it tells you what to find out, and you do the registering yourself.", ["The NCAA international students page, open to read", "Your school marks, if you have them"], "ncaaInternational", "you can say the number of core courses and the two GPA lines for Division I and Division II.", [W("Core course", "a school subject that the NCAA counts toward eligibility."), W("GPA", "grade point average: your marks averaged into one number."), W("Eligibility Center", "the NCAA office that checks whether an athlete may play.")]),
      S("Learn what to register and send", "You register with the Eligibility Center. You give transcripts from the ninth year of school and proof of graduation. Records in another language need a complete, word-for-word certified English translation. The NCAA prefers that a member school uploads them. Start collecting your records early.", ["Transcripts from the ninth year onward", "Proof of graduation", "The Eligibility Center registration page"], "ncaaInternational", "you have a list of which records you have and which you still need, including any that need translation.", [W("Transcript", "the official record of your school marks."), W("Certified translation", "a translation that someone qualified has signed to say it is complete and true.")]),
      S("Look for your country profile", "The NCAA groups country profiles by region and links an academic-requirements document for each. I could not read those for Kenya or Nigeria. So ask the school's compliance office what your country's marks and exams count for. Write down who you asked and what they said.", ["The name of your country", "The NCAA international page, open", "Paper and a pen"], "ncaaInternational", "you have written your question about your country's marks for the school's compliance office.", [W("Compliance office", "the school office that explains the rules to athletes."), W("Country profile", "an NCAA page on one country's school system.")]),
      S("Learn about the April 2026 change for prize money and agents", "The NCAA said on 15 April 2026 that Division I prospects enrolling in 2026-27 can now accept prize money in their sport, enter a draft once and sign with a professional agent before enrolling, without losing eligibility. It did not say whether this applies to international prospects, and it said nothing about signed professional contracts. So ask the compliance office before you do any of these.", ["The NCAA news item, open to read"], "ncaaProspects2026", "you know the change was announced for Division I prospects and that the page does not say it covers international prospects.", [W("Prospect", "a person who has not yet enrolled in college but may play there.")]),
      S("Learn the NAIA fee and timing", "The NAIA says an international student pays a one-time, non-refundable registration fee of 170 dollars. You must also buy a records evaluation from the evaluator the NAIA page names, at a price its page does not list. You should submit everything at least two months before starting, with records in the original language and a literal word-for-word English translation.", ["The NAIA international students page, open to read", "A calendar to count back two months from your start date"], "naiaInternational", "you can say the fee, that the evaluation costs extra, and the two months rule.", [W("NAIA", "a group of colleges that has its own rules for athletes, separate from the NCAA."), W("Non-refundable", "you do not get the money back.")]),
      S("Write what the guide could not read", OWN + "I could not read the NJCAA's rules or any NCAA fee amount. Write those as questions for the school's compliance office. Add the evaluation price and your country profile. Then ask, and write down each answer with the date.", ["Paper and a pen", "The email of the school's compliance office"], null, "you have a written list of questions about the NJCAA rules, the NCAA fees and the evaluation price.", [W("NJCAA", "a group of two-year colleges with their own sport rules.")])
    ]
  },

  // ---------------------------------------------------------------- US tax for an international student-athlete
  "abroad-tax": {
    title: "Learning the US tax basics for an international student-athlete",
    topic: "athlete-abroad-tax", phrase: "taxes for an international student athlete in the United States",
    steps: [
      S("Learn which form a foreign student files", "The IRS says a foreign student on an F, J, M or Q visa who has taxable income, including a taxable scholarship or fellowship grant, files Form 1040-NR. This is a lesson, not tax advice: it tells you what the IRS page says so you can ask good questions.", ["The IRS foreign students page, open to read", "Paper and a pen"], "irsForeignStudents", "you can say the name of the form and who the IRS says files it.", [W("IRS", "the United States tax authority."), W("Form 1040-NR", "the tax return for a person who is not a US resident for tax."), W("Fellowship grant", "money given to a student to study.")]),
      S("Learn what part of a scholarship is tax free", "The IRS says a scholarship is tax free only for a degree candidate and only up to tuition, required fees and required books and supplies. Room and board, travel and payment for services are taxable. So read your scholarship letter and mark which parts are which.", ["Your scholarship letter", "The IRS foreign students page, open"], "irsForeignStudents", "you have marked on your letter which parts the IRS lists as tax free and which as taxable.", [W("Degree candidate", "a student who is working toward a degree."), W("Room and board", "the cost of a place to live and meals.")]),
      S("Learn about Form 8843 and counting days", "The IRS says a student must file Form 8843 to exclude days from counting as time in the United States. A student is generally exempt from counting days for up to five calendar years. Keep a note of the dates you have been in the United States.", ["The IRS exempt student page, open to read", "The dates you have been in the United States"], "irsExemptStudent", "you can say what Form 8843 is for and the number of calendar years a student is generally exempt from counting days.", [W("Form 8843", "a form a student files to say certain days should not count as time in the United States."), W("Exempt", "not required to count or pay.")]),
      S("Learn about withholding", "Publication 519 says withholding on a US grant that is not fully exempt is 14 percent, or a lower treaty rate. It also says social security and Medicare tax is generally not withheld on a nonresident student's pay for work. Withholding means tax taken out before the money reaches you.", ["The IRS Publication 519 page, open to read"], "irsP519", "you can say the withholding rate on a grant that is not fully exempt, and that a lower treaty rate may apply.", [W("Withholding", "tax taken out of a payment before it reaches you."), W("Treaty", "an agreement between two countries, here about tax.")]),
      S("Check whether your country has a tax treaty", "The IRS's list of countries with a US tax treaty does not include Kenya or Nigeria. For Africa it lists Egypt, Morocco, South Africa and Tunisia. So a treaty exemption for a Kenyan or Nigerian student is not shown there. Look at the list for your own country.", ["The name of your country", "The IRS treaty list, open to read"], "irsTreaties", "you have looked for your country on the list and written whether it is there.", [W("Tax treaty", "an agreement that can lower or remove tax for people of one country earning money in another.")]),
      S("Learn when the return is due", "The IRS says the return is generally due on 15 April, or 15 June if you have no US wages subject to withholding. Put the right date on your calendar now, so that it does not slip by.", ["A calendar or diary", "The IRS taxation of nonresident aliens page, open"], "irsNonresident", "you have written the due date that fits you on your calendar.", [W("Nonresident alien", "the IRS's name for a person who is not a US resident for tax.")]),
      S("Know what the guide cannot say, and who to ask", OWN + "I did not read the last part of Publication 519. The guide does not say how name, image and likeness income is taxed for a nonresident student. A tax professional who knows international students should read your case. Write down your income, your visa and your country, and take them with you.", ["Paper and a pen", "Your scholarship letter and a note of any other income"], null, "you have a written list of your income and visa details to give a tax professional who knows international students.", [W("Name, image and likeness", "being paid for the use of your name, picture or fame.")])
    ]
  },

  // ---------------------------------------------------------------- scams aimed at international athletes
  "abroad-scams": {
    title: "Spotting scholarship and visa scams aimed at international athletes",
    topic: "athlete-abroad-scams", phrase: "spotting scholarship and visa scams aimed at international athletes",
    steps: [
      S("Check before you pay anything", "Before you pay anything, check. The FTC says never to pay to apply for a scholarship. Talk to the school's financial aid office first. Ask for the total cost and the refund policy in writing. The page is written for US students and says nothing about sports recruiters or agents, so use the same care with them.", ["The name of the scholarship or the person asking for money", "Paper and a pen"], "ftcScholarshipScams", "you have not paid, and you have written the name of the school's financial aid office to contact first.", [W("FTC", "the Federal Trade Commission, a US government body that protects buyers."), W("Financial aid office", "the school office that handles money for students."), W("Refund policy", "the rules about getting your money back.")]),
      S("Know the lines to walk away from", "The FTC lists lines to walk away from. One is a scholarship that is guaranteed, or your money back. Another is a request for your card or bank number to hold it. Another is we do all the work for a processing fee. Another is being a finalist in a contest you never entered. If you hear any of these, stop.", ["The message or advertisement you received"], "ftcScholarshipScams", "you have checked the message against all four lines and marked any that match.", [W("Processing fee", "a charge for handling your papers."), W("Finalist", "someone chosen to be in the last group of a contest.")]),
      S("Know the phone call scam", "A 2019 FTC alert says scammers have phoned international students posing as government officials. They claimed a visa or immigration problem. They demanded immediate payment by gift cards or cryptocurrency and threatened arrest or deportation. The alert says the federal government would not ask for such payments. Hang up and check with someone you trust.", ["The name of someone you trust to call afterwards"], "ftcInternationalStudents", "you can say that paying by gift card or cryptocurrency on a phone call is a warning sign, and who you would call.", [W("Cryptocurrency", "digital money that is not issued by a government."), W("Deportation", "being made to leave a country.")]),
      S("Know the visa fraud warning", "The State Department's fraud warning says fraudulent organisations may charge for free information or promise visas they cannot deliver. It says payments to non-government sources do not apply to visa processing. A visa email or website not ending in dot gov should be treated as suspect.", ["The State Department fraud warning page, open to read", "Any visa email or website address you have received"], "stateVisaFraud", "you have checked each visa email or website address you have and marked any that does not end in dot gov.", [W("Fraudulent", "dishonest and meant to cheat.")]),
      S("Report it and ask for help", "If you think something is a scam, the FTC says to report it on its fraud reporting website. Do not send more money. I could not read EducationUSA, the State Department's adviser service for students abroad, so I cannot quote its warning about agents who charge. Ask someone you trust before you pay.", ["The FTC scholarship scam page, open", "The message or papers you want to report"], "ftcScholarshipScams", "you know where to report a scam and you have not sent any money.", [W("Report", "to tell the authorities so they can act and warn others.")])
    ]
  },

  // ---------------------------------------------------------------- running a youth sports club
  "club": {
    title: "Learning the basics of running a youth sports club or league",
    topic: "athlete-club", phrase: "running a youth sports club or league", us: true,
    steps: [
      S("Learn the tax-exempt purpose that mentions sport", "The IRS lists fostering national or international amateur sports competition among the exempt purposes under section 501(c)(3). That is the first thing to know if you hope your club will be tax exempt. This is a lesson, not tax advice, and a tax professional can tell you more.", ["The IRS exempt purposes page, open to read", "Paper and a pen"], "irsExemptPurposes", "you can say which sport purpose the IRS lists under section 501(c)(3).", [W("501(c)(3)", "the part of the tax law that describes charities that are exempt from income tax."), W("Tax exempt", "not required to pay income tax.")]),
      S("Read the catch about athletic facilities and equipment", "IRS Publication 557 says an organization with that purpose qualifies only if none of its activities involve providing athletic facilities or equipment. A qualified amateur sports organization is a separate kind that can provide them. The pages I read do not say how the IRS treats a local youth league, so a tax professional can tell you.", ["IRS Publication 557, open to read", "A list of what your club would provide, such as fields or equipment"], "irsP557", "you have listed whether your club would provide facilities or equipment, and you know to ask a tax professional.", [W("Amateur sports organization", "a group that runs sport for people who are not paid players.")]),
      S("Learn about social and recreation clubs", "Publication 557 also describes social and recreation clubs under section 501(c)(7), including some sport clubs. They have limited membership and are supported by dues. It says a small organization with assets of 250,000 dollars or less and gross receipts of 50,000 dollars or less can use the short Form 1023-EZ.", ["IRS Publication 557, open to read", "A rough idea of your club's money"], "irsP557", "you can say what a social club is in the IRS's words and the two money limits for the short form.", [W("Dues", "regular payments members make to belong."), W("Gross receipts", "all the money an organization takes in.")]),
      S("Learn about liability insurance", "The SBA lists general liability insurance for bodily injury and property damage. For a youth club, that means thinking about what happens if someone is hurt or property is damaged. The guide does not say how much cover a club needs.", ["The SBA insurance page, open to read", "Paper and a pen"], "sbaInsurance", "you can say what general liability insurance covers, in the SBA's words.", [W("SBA", "the Small Business Administration, a US government agency for small businesses."), W("Liability", "being legally responsible if someone is hurt or something is damaged.")]),
      S("Take the free concussion training for coaches", "The CDC offers free online concussion training for youth sports coaches. A person who coaches your club's teams can take it. You do the training yourself on the official page.", ["The CDC training page, open", "An email address to sign up with"], "cdcHeadsCoaches", "you or a coach have opened the training page and decided who will take it.", [W("Concussion", "an injury to the brain caused by a blow to the head or body.")]),
      S("Learn about the abuse prevention rules", "Organizations in the Olympic and Paralympic movement must follow the Minor Athlete Abuse Prevention Policies. Read them if your club is part of that movement. For waivers, ask me about liability waivers, because the rules differ by state. I found no official page on registration fees or dues, so I will not say what to charge.", ["The Minor Athlete Abuse Prevention Policies page, open to read"], "safesportMaapp", "you know whether the policies apply to your club and you know the guide does not say what to charge.", [W("Minor Athlete Abuse Prevention Policies", "rules that protect young athletes from abuse, which Olympic and Paralympic movement groups must follow.")])
    ]
  },

  // ---------------------------------------------------------------- money and a career after sport (a lesson)
  "money": {
    title: "Learning the basics of money and a career after sport",
    topic: "athlete-money", phrase: "money and a career after sport", us: true,
    steps: [
      S("Learn why savings come first", "The CFPB says that without savings even a small shock can push you into credit cards or loans. It gives no fixed amount to save. If your income is irregular or comes in one-time sums, it says to save part of it, and move extra into savings in better weeks. This is a lesson, not financial advice.", ["The CFPB page, open to read", "Paper and a pen"], "cfpbEmergencyFund", "you can say why savings matter and what the CFPB says to do with income that comes in one-time sums.", [W("CFPB", "the Consumer Financial Protection Bureau, a US government agency for money matters."), W("Irregular income", "money that comes at uneven times or in uneven amounts.")]),
      S("Learn the difference between saving and investing", "Investor.gov says saving and investing both mean setting aside some of what you earn. A savings account suits short-term goals or an emergency fund. Investing means putting money into assets such as stocks or bonds, expecting a return over time. All investments involve risk, and there is no set rate of return.", ["The Investor.gov page, open to read"], "investorGovIntro", "you can say the difference between saving and investing, and that all investing has risk.", [W("Asset", "something you own that has value."), W("Return", "the money you gain from an investment.")]),
      S("Learn what stocks, bonds and diversification are", "FINRA says owning stock makes you a part owner of a company. A bond is debt that the issuer repays with interest. A fund can hold dozens or even thousands of securities. It says to learn about diversification, so you do not bet the ranch on one investment.", ["The FINRA investing basics page, open to read"], "finraBasics", "you can say in your own words what stock, a bond and diversification are.", [W("Diversification", "spreading your money across many investments so one loss does not ruin you."), W("Security", "a stock, a bond or a similar investment."), W("Issuer", "the company or government that sells a bond.")]),
      S("Learn about fund fees", "FINRA says all mutual funds have fees and expenses. One kind of fee, the 12b-1 fee, is capped at 1 percent of assets. Look for the fees before you decide on a fund.", ["The FINRA mutual funds page, open to read"], "finraMutualFunds", "you can say that all mutual funds have fees and expenses.", [W("Mutual fund", "a pool of many people's money that is invested together."), W("12b-1 fee", "a yearly fee some funds charge, capped at 1 percent of assets.")]),
      S("Learn the warning signs of a scam that targets groups", "An older SEC page from 2013 says scams that target groups, including professional groups, often use trusted members of the group. It lists the warning signs. They are promises of guaranteed or unusually high returns, no written details, pressure to act quickly, and reliance on someone else having made money.", ["The SEC page, open to read"], "secAffinity", "you can name the four warning signs.", [W("Affinity fraud", "a scam that spreads through a group whose members trust each other.")]),
      S("Learn what to do about unsolicited pitches", "FINRA's advice against fraud is to decline unsolicited pitches, to check the seller's registration on BrokerCheck, and to talk to a trusted person first. An unsolicited pitch is an offer you did not ask for.", ["The FINRA avoid fraud page, open to read", "The name of a trusted person"], "finraFraud", "you can say the three things FINRA advises and you have named a trusted person.", [W("BrokerCheck", "a FINRA tool for checking whether a seller of investments is registered."), W("Unsolicited", "not asked for.")]),
      S("Check an adviser before you trust one", "The CFPB's adviser flyer lists BrokerCheck and the SEC's adviser database to check a regulated adviser. It says to ask how an adviser is paid and to get conflicts of interest in writing.", ["The CFPB adviser flyer, open to read", "The name of any adviser you are thinking of"], "cfpbAdviser", "you can name the two places to check an adviser and the two things to ask.", [W("Adviser", "a person who gives advice about money for a fee or a commission."), W("Conflict of interest", "a situation where the adviser could gain from advice that does not help you.")]),
      S("Learn about retirement plans for the self-employed", "For someone who is self-employed, the IRS describes retirement plans such as a SEP, a one-participant 401(k) and a SIMPLE IRA. The dollar limits on its page were out of date, so check the IRS for this year's. For pensions and disability cover, ask me about athlete pensions.", ["The IRS retirement plans page, open to read"], "irsRetirementSelfEmployed", "you can name the three plans and you know to check the IRS for this year's limits.", [W("Self-employed", "working for yourself instead of an employer."), W("SEP", "a retirement plan a self-employed person can set up.")])
    ]
  }
};
